<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">&#x2190;</text><text class="nav-title">&#x8BB0;&#x5FC6;&#x7FFB;&#x724C;</text><text class="nav-icon" @click="resetGame">&#x1F504;</text></view></view><view class="content"><view class="stats-row"><text class="stat">&#x6B21;&#x6570;: {{ moves }}</text><text class="stat">&#x65F6;&#x95F4;: {{ formattedTime }}</text><text class="stat">&#x6700;&#x4F73;: {{ bestMoves }}</text></view><view class="diff-row"><view class="diff-btn" :class="{active: level===16}" @click="level=16;resetGame()">4x4</view><view class="diff-btn" :class="{active: level===20}" @click="level=20;resetGame()">4x5</view><view class="diff-btn" :class="{active: level===36}" @click="level=36;resetGame()">6x6</view></view><view class="card-grid" :style="{gridTemplateColumns: 'repeat('+gridCols+',1fr)'}"><view class="card" v-for="(card, idx) in cards" :key="idx" :class="{flipped: card.flipped, matched: card.matched}" @click="flipCard(idx)"><view class="card-inner"><view class="card-front" v-if="card.flipped || card.matched">{{ card.symbol }}</view><view class="card-back" v-else>?</view></view></view></view><view v-if="gameWon" class="win-overlay"><text class="win-text">&#x1F389; &#x606D;&#x559C;&#x901A;&#x5173;</text><view class="restart-btn" @click="resetGame"><text>&#x518D;&#x73A9;&#x4E00;&#x6B21;</text></view></view></view></view></template><script setup>import { ref, computed, onMounted, onUnmounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const symbols = ["&#x1F600;","&#x1F60D;","&#x1F929;","&#x1F60E;","&#x1F914;","&#x1F60F;","&#x1F61C;","&#x1F910;","&#x1F631;","&#x1F634;","&#x1F608;","&#x1F92F;","&#x1F61A;","&#x1F607;","&#x1F920;","&#x1F917;","&#x1F61D;","&#x1F61E;"]
const cards = ref([])
const level = ref(16)
const moves = ref(0)
const seconds = ref(0)
const bestMoves = ref(999)
const gameWon = ref(false)
const flippedIndices = ref([])
var timer = null
const gridCols = computed(function() { return level.value === 36 ? 6 : 4 })
const formattedTime = computed(function() { var m = Math.floor(seconds.value/60); var s = seconds.value%60; return (m<10?"0":"")+m+":"+(s<10?"0":"")+s })
function goBack() { uni.navigateBack(); clearInterval(timer) }
function resetGame() { clearInterval(timer); moves.value = 0; seconds.value = 0; gameWon.value = false; flippedIndices.value = []; var pairs = level.value / 2; var selected = symbols.slice(0, pairs); var all = selected.concat(selected).sort(function(){return Math.random()-0.5}); cards.value = all.map(function(s) { return { symbol: s, flipped: false, matched: false } }); timer = setInterval(function() { seconds.value++ }, 1000) }
function flipCard(idx) { if (cards.value[idx].flipped || cards.value[idx].matched) return; if (flippedIndices.value.length >= 2) return; cards.value[idx].flipped = true; flippedIndices.value.push(idx); if (flippedIndices.value.length === 2) { moves.value++; var i1 = flippedIndices.value[0], i2 = flippedIndices.value[1]; if (cards.value[i1].symbol === cards.value[i2].symbol) { cards.value[i1].matched = true; cards.value[i2].matched = true; flippedIndices.value = []; checkWin() } else { var fi = flippedIndices.value.slice(); setTimeout(function() { cards.value[fi[0]].flipped = false; cards.value[fi[1]].flipped = false; flippedIndices.value = [] }, 800) } } }
function checkWin() { if (cards.value.every(function(c){return c.matched})) { gameWon.value = true; clearInterval(timer); if (moves.value < bestMoves.value) bestMoves.value = moves.value } }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } resetGame() })
onUnmounted(function() { clearInterval(timer) })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#f43f5e,#e11d48);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:44rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.stats-row{display:flex;justify-content:space-between;margin-bottom:16rpx}.stat{font-size:24rpx;color:#666}.diff-row{display:flex;gap:12rpx;margin-bottom:16rpx}.diff-btn{flex:1;padding:12rpx;text-align:center;background:#fff;border-radius:12rpx;font-size:26rpx;color:#666}.diff-btn.active{background:linear-gradient(135deg,#f43f5e,#e11d48);color:#fff}.card-grid{display:grid;gap:12rpx}.card{aspect-ratio:1;background:#fff;border-radius:16rpx;display:flex;align-items:center;justify-content:center;box-shadow:0 4rpx 16rpx rgba(0,0,0,.08);transition:all .3s}.card.flipped{background:linear-gradient(135deg,#fef3c7,#fde68a)}.card.matched{background:linear-gradient(135deg,#d1fae5,#6ee7b7)}.card-inner{font-size:48rpx}.card-back{font-size:48rpx;color:#ccc}.win-overlay{position:fixed;inset:0;background:rgba(0,0,0,.7);display:flex;flex-direction:column;align-items:center;justify-content:center;z-index:99}.win-text{color:#fff;font-size:40rpx;font-weight:700}.restart-btn{background:linear-gradient(135deg,#f43f5e,#e11d48);border-radius:16rpx;padding:24rpx 48rpx;margin-top:24rpx}.restart-btn text{color:#fff;font-size:30rpx}</style>